export function calcMaterialCostPerM2(
  widthMm: number,
  lengthMm: number,
  boardPrice: number,
  wastePercent: number,
): number {
  if (widthMm <= 0 || lengthMm <= 0) return 0;
  const areaM2 = (widthMm * lengthMm) / 1_000_000;
  const baseCost = boardPrice / areaM2;
  return baseCost * (1 + wastePercent / 100);
}

