	}
	var c roleBindingContract
	if err := json.Unmarshal(raw, &c); err != nil {
		t.Fatalf("parse shared contract: %v", err)
	}
	if len(c.AliasCases) == 0 || len(c.BindingCases) == 0 {
		t.Fatalf("shared contract must carry alias and binding cases")
	}
	return c
}

