toast: (input) => {
  const id = nextToastId();
  const message = input.message.trim();
  if (!message) return;

  // P1-6 (pre-demo audit): repeated identical errors (e.g. one per
  // failed catalog save) stacked up as five copies of the same message.
  // Refresh the lifetime of the live twin instead of stacking a clone.
  const state0 = get();
  const twin = state0.items.find(
    (t) =>
      t.phase !== 'exit' &&
      t.type === input.type &&
      t.message === message,
  );
  if (twin) {
    set((state) => ({
      items: state.items.map((t) =>
        t.id === twin.id && t.phase === 'enter'
          ? { ...t, phase: 'visible' as const }
          : t,
      ),
    }));
    scheduleAutoDismiss(twin.id);
    return;
  }

  set((state) => {
    const overflow = state.items.filter((t) => t.phase !== 'exit');
    // Cap at TOAST_MAX: mark oldest for exit on next macrotask so
    // the CSS exit animation runs.
    if (overflow.length >= TOAST_MAX) {
      const oldest = overflow[0]!;
      setTimeout(() => beginExit(oldest.id), 0);
    }
    return {
      items: [
        ...state.items,
        {
          id,
          type: input.type,
          message,
          phase: 'enter' as const,
        },
      ],
    };
  });

  // Enter → visible on next frame so CSS transition runs.
  const enterHandle = setTimeout(() => {
    enterTimers.delete(id);
    set((state) => ({
      items: state.items.map((t) =>
        t.id === id && t.phase === 'enter'
          ? { ...t, phase: 'visible' as const }
          : t,
      ),
    }));
  }, 16);
  enterTimers.set(id, enterHandle);

  scheduleAutoDismiss(id);

