      // Posiciones originales: el undo restaura cada línea en su lugar.
      itemOrderBefore: project.items.map((i) => i.id),
      ts: Date.now(),
    }),
  ]);
  setRedoStack([]);
  // El store quita también los placements de las líneas eliminadas.
